<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<section class="py-4 border-bottom bg-light"><div class="container"><h1 class="h3 mb-1">My Orders</h1><p class="text-muted mb-0">Track past and current orders.</p></div></section>
<section class="py-5"><div class="container"><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Order</th><th>Status</th><th>Payment</th><th>Total</th><th>Date</th></tr></thead><tbody>
	<?php if (empty($orders)): ?><tr><td colspan="5"><?php echo empty_state('No orders yet', 'Your purchases will appear here.', 'fa-box-open', array('label' => 'Shop Now', 'url' => site_url('shop'), 'icon' => 'fa-bag-shopping')); ?></td></tr><?php else: foreach ($orders as $order): ?><tr><td><a href="<?php echo site_url('account/orders/'.$order->id); ?>"><?php echo html_escape($order->order_number); ?></a></td><td><?php echo status_badge($order->order_status, 'order'); ?></td><td><?php echo status_badge($order->payment_status, 'payment'); ?></td><td><?php echo money($order->total_amount); ?></td><td><?php echo format_datetime($order->created_at); ?></td></tr><?php endforeach; endif; ?>
</tbody></table></div></div></div></section>
